// src/players/skills/. Do not edit: edit the live kit, then refresh when the
// baselines should follow it.
import { ActionType, EffectHandler, FATIGUE_MAX_LEVEL, StatusBehavior } from '@pimpampum/engine';
import { SkillDefinition, action, d, ICON_PREFIX } from '../../players/types.js';
import { num, diceParam, applyMod, durParam } from '../../players/effects/helpers.js';

/**
 * Berserk — a D&D-style barbarian whose power is raw, escalating wrath, not technique.
 * Weapon-agnostic like the Mestre d'Armes: attack cards roll their OWN dice plus the
 * wielded weapon's modifier (`weapon_damage`, weapon required), but here the fury is
 * what lands and amplifies it — reckless
 * swings, the rage STATE (+5 dealt / −5 taken), wound-scaling, and a last-stand
 * capstone. Handlers and status behaviours live below, on this SkillDefinition.
 */

// The rage state: a visible marker; the +value attack boost lives on a
// CombatModifier set by enter_rage (roll space, never damage space).
const FURIA_ESTAT: StatusBehavior = {};

// Entrar en Fúria: NOTHING can lower the raging holder's PV while it lasts.
const INDESTRUCTIBLE: StatusBehavior = {
  clampPvLoss() { return 0; },
  /**
   * Hands back exactly the health the evaluator thinks was lost.
   *
   * Entering the rage slams the berserker to 1 PV, which `positionScore` reads
   * as very nearly dead — so the search refused to enter it: the card was
   * played on 1.0% of the turns it was legal, the deadest in the game. But
   * while the rage lasts that 1 PV cannot be taken, so the right reading is
   * that the holder is at FULL effective health, not at one point of it.
   */
  positionValue(ref) {
    const missing = ref.holder.maxPV - Math.max(0, ref.holder.currentPV);
    return missing / Math.max(1, ref.holder.maxPV);
  },
};
/**
 * Aguantar el cop: braced, not defenceless — no contest is rolled and every
 * blow lands, but lighter: divided by `divisor` (rounded up), less a flat
 * `soak`. `data` carries the card's params.
 */
const AGUANTANT: StatusBehavior = {
  absorbsGuard() { return true; },
  modifyIncomingDamage(ctx, damage) {
    const d = ctx.entry.data ?? {};
    d['blow'] = damage; // the full blow braced against, read back by onBlockFail
    damage = Math.ceil(damage / Math.max(1, num(d, 'divisor', 1)));
    return Math.max(0, damage - num(d, 'soak', 0));
  },
};

const BERSERK_EFFECTS: Record<string, EffectHandler> = {
  // Entrar en Fúria: enter the battle-trance, all in. The berserkergang is
  // followed by exhaustion, so EVERY rage costs a fatigue level, and an
  // exhausted (Esgotat) berserker cannot rage at all. Free to re-enter, a
  // berserker already at 1 PV lost nothing by going again and stayed
  // indestructible for the rest of the fight: 14% of his fights at the fury
  // level ran to the round cap (NEXT-STEPS §26). Entering slams the body to
  // 1 PV; while the rage lasts the holder's attack rolls get +value and
  // NOTHING can lower their PV (INDESTRUCTIBLE).
  'enter_rage@cal': {
    getTargetRequirement() { return 'none'; },
    canPlay(actor) { return actor.fatigue < FATIGUE_MAX_LEVEL; },
    onResolve(ctx) {
      ctx.source.setFatigue(ctx.source.fatigue + 1);
      const value = num(ctx.params, 'value', 5);
      const turns = num(ctx.params, 'turns', 3);
      applyMod(ctx.source, 'attack', value, turns, 'Fúria');
      // One tick more than the card's turns: a status counts down at the end of
      // the round it was set in, so set to `turns` the rage protected for one
      // round after it resolved, while the +5 above (a modifier that skips
      // that first tick) ran for both.
      ctx.source.setStatus('furia', value, turns + 1, undefined, FURIA_ESTAT);
      // The all-in: the rage burns the body down to its last breath (a direct
      // set — no hit is recorded, so it interrupts nothing).
      ctx.source.currentPV = 1;
      ctx.source.setStatus('indestructible', 1, turns + 1, undefined, INDESTRUCTIBLE);
      ctx.engine.log('focus', `${ctx.source.name} entra en fúria: 1 PV, intocable ${turns} torns i +${value} a l'atac!`, ctx.source.team);
    },
    // The lower the berserker already is, the less the all-in costs.
    aiWeight(ctx) {
      if (ctx.actor.hasStatus('furia')) return 0;
      return 0.5 + 1.5 * (1 - ctx.actor.currentPV / ctx.actor.maxPV);
    },
  },

  // Rugit de guerra: a terrifying war cry. Each enemy rolls a d20; below
  // `below` it freezes, and loses its action if it has not acted yet
  // (engine `cancelPendingAction`, speed-gated — the roar wants high speed).
  // A flat chance, not a contest: as a contest it added the berserker's level
  // and not the enemy's, cowed ~70% of the field at level 5 and decided the
  // strategy triangle on its own (NEXT-STEPS §27.6).
  'fear_roar@cal': {
    getTargetRequirement() { return 'none'; },
    onResolve(ctx) {
      const below = num(ctx.params, 'below', 10);
      for (const t of ctx.engine.enemiesOf(ctx.source)) {
        const roll = ctx.engine.rollDie(20);
        const ok = roll < below;
        ctx.engine.log('focus', `🎲 Rugit de guerra: ${t.name} treu ${roll} → ${ok ? 'aterrit' : 'resisteix'}.`, ctx.source.team);
        if (!ok) continue;
        const cancelled = ctx.engine.cancelPendingAction(t);
        ctx.engine.log('focus', cancelled
          ? `${t.name} queda paralitzat per la por i perd l'acció.`
          : `${t.name} ja havia actuat: el rugit no hi arriba a temps.`, ctx.source.team);
      }
    },
    aiWeight(ctx) { return ctx.enemies.length >= 1 ? 1.5 : 0; },
  },

  // Aguantar el cop: no guard roll; blows land lighter (AGUANTANT above) and
  // what he takes becomes +{A} on his attacks NEXT TURN only. For the rest of
  // combat it stacked without limit: a berserker blocking round after round
  // banked over +20 and hit for 45 (NEXT-STEPS §32, §36).
  'rage_from_pain@cal': {
    getTargetRequirement() { return 'none'; },
    onResolve(ctx) {
      ctx.source.setStatus('aguantant', 1, 1, { divisor: num(ctx.params, 'divisor', 1), soak: num(ctx.params, 'soak', 0) }, AGUANTANT);
    },
    onBlockFail(ctx) {
      const taken = ctx.damageDealt ?? 0;
      const blow = num(ctx.source.getStatus('aguantant')?.data ?? {}, 'blow', taken);
      const basis = ctx.params['fromBlow'] ? blow : taken;
      if (basis <= 0) return;
      const gain = basis * num(ctx.params, 'multiplier', 2);
      const duration = durParam(ctx.params, 'duration', 'restOfCombat');
      applyMod(ctx.source, 'attack', gain, duration, ctx.action.name);
      const lasts = duration === 'restOfCombat' ? 'la resta del combat'
        : duration === 'nextTurn' ? 'el torn següent' : `${duration} torns`;
      ctx.engine.log('defense', `${ctx.source.name} canalitza el dolor: +${gain} {A} ${lasts}.`, ctx.source.team);
    },
    // A gamble, so not the favourite; but the depth-0 heuristic must let the
    // search consider it at all.
    aiWeight() { return 1.1; },
  },

};

